+const fs = require("fs");
+const readline = require("readline");
+
+const path = String.raw`C:\Users\Svetl\Downloads\Telegram Desktop\All Keywords.normalized.csv`;
+
+const terms = [
+  "academic",
+  "research",
+  "scientific",
+  "journal",
+  "publication",
+  "scholarly",
+  "peer review",
+  "peer-review",
+  "retraction",
+  "retract",
+  "paper mill",
+  "hindawi",
+  "wiley",
+  "frontiers",
+  "preprint",
+  "plagiarism",
+  "integrity",
+  "ethics",
+  "fraud",
+  "fabricat",
+  "fake",
+  "citation",
+  "citing",
+  "reference",
+];
+
+function parseCSVLine(line) {
+  const out = [];
+  let cur = "";
+  let inQ = false;
+  for (let i = 0; i < line.length; i++) {
+    const ch = line[i];
+    if (inQ) {
+      if (ch === '"') {
+        if (line[i + 1] === '"') {
+          cur += '"';
+          i++;
+        } else {
+          inQ = false;
+        }
+      } else {
+        cur += ch;
+      }
+    } else {
+      if (ch === ",") {
+        out.push(cur);
+        cur = "";
+      } else if (ch === '"') {
+        inQ = true;
+      } else {
+        cur += ch;
+      }
+    }
+  }
+  out.push(cur);
+  return out;
+}
+
+async function main() {
+  const stream = fs.createReadStream(path, { encoding: "utf8" });
+  const rli = readline.createInterface({ input: stream, crlfDelay: Infinity });
+
+  let header = null;
+  let total = 0;
+  const rows = [];
+
+  for await (const line of rli) {
+    if (!header) {
+      header = parseCSVLine(line);
+      continue;
+    }
+
+    total++;
+    const cols = parseCSVLine(line);
+    if (cols.length < header.length) continue;
+
+    const rec = {};
+    for (let i = 0; i < header.length; i++) rec[header[i]] = cols[i] ?? "";
+
+    const hay = ((rec.keyword_norm ?? "") + " " + (rec.keyword ?? "")).toLowerCase();
+    if (!terms.some((t) => hay.includes(t))) continue;
+
+    rows.push({
+      keyword: rec.keyword,
+      keyword_norm: rec.keyword_norm,
+      volume: Number(rec.volume) || 0,
+      intent: rec.intent,
+      cluster: rec.cluster,
+      subcluster: rec.subcluster,
+      competitor_brand: rec.competitor_brand,
+      is_competitor: rec.is_competitor,
+    });
+  }
+
+  rows.sort((a, b) => b.volume - a.volume);
+  console.log(`total=${total} matches=${rows.length}`);
+  for (const r of rows.slice(0, 80)) {
+    console.log(
+      [
+        r.keyword,
+        r.volume,
+        r.intent,
+        r.cluster,
+        r.subcluster,
+        r.is_competitor,
+        r.competitor_brand,
+      ].join("\t"),
+    );
+  }
+}
+
+main().catch((e) => {
+  console.error(e?.stack || String(e));
+  process.exit(1);
+});
+
